/* Waldatmosphäre */
.forest-ambient{position:absolute;inset:0;z-index:7;overflow:hidden;pointer-events:none}
.sunbeam{position:absolute;top:-20%;width:110px;height:125%;background:linear-gradient(180deg,rgba(255,250,190,.34),rgba(255,241,151,.03));filter:blur(10px);transform:rotate(16deg);animation:beamMove 11s ease-in-out infinite alternate}
.beam-1{left:37%}.beam-2{left:56%;animation-delay:-5s;opacity:.55}
@keyframes beamMove{from{transform:translateX(-18px) rotate(16deg);opacity:.35}to{transform:translateX(30px) rotate(20deg);opacity:.72}}
.forest-bird,.forest-butterfly{position:absolute;filter:drop-shadow(0 4px 4px rgba(32,58,25,.25))}
.bird-1{top:34%;left:61%;font-size:20px;animation:birdHop 10s ease-in-out infinite}.bird-2{top:29%;left:69%;font-size:15px;animation:birdHop 12s ease-in-out infinite reverse}
@keyframes birdHop{0%,75%,100%{transform:translate(0,0)}82%{transform:translate(40px,-20px)}88%{transform:translate(80px,2px)}}
.butterfly-1{top:37%;left:28%;font-size:24px;animation:butterflyWander 12s ease-in-out infinite}
@keyframes butterflyWander{0%,100%{transform:translate(0,0) rotate(-12deg)}25%{transform:translate(90px,-35px) rotate(8deg)}55%{transform:translate(180px,15px) rotate(-5deg)}80%{transform:translate(85px,45px) rotate(10deg)}}
/* kurzer Wow-Effekt beim ersten Öffnen */
.morning-intro{position:absolute;inset:0;z-index:300;display:grid;place-items:center;background:radial-gradient(circle at 50% 45%,rgba(255,251,202,.97),rgba(35,102,48,.96));animation:introHide 4.4s ease forwards;pointer-events:none}
.intro-sun{position:absolute;width:320px;height:320px;border-radius:50%;background:radial-gradient(circle,#fffde0 0 18%,#ffe96d 38%,rgba(255,224,84,.05) 72%);animation:sunRise 3.8s ease forwards}
.intro-fox{position:relative;font-size:120px;filter:drop-shadow(0 18px 16px rgba(25,53,28,.35));animation:foxEnter 3.6s ease forwards}
.intro-text{position:absolute;top:68%;font-size:34px;font-weight:900;color:#fff;text-shadow:0 4px 10px rgba(26,61,31,.6);animation:textEnter 3.5s ease forwards}
@keyframes sunRise{0%{transform:translateY(260px) scale(.35);opacity:0}50%{opacity:1}100%{transform:translateY(-70px) scale(1.5);opacity:.55}}
@keyframes foxEnter{0%{transform:translateX(-55vw) rotate(-10deg);opacity:0}45%{opacity:1}75%{transform:translateX(0) rotate(3deg)}100%{transform:translateX(0) rotate(0)}}
@keyframes textEnter{0%,42%{opacity:0;transform:translateY(20px)}70%,100%{opacity:1;transform:none}}
@keyframes introHide{0%,72%{opacity:1;visibility:visible}100%{opacity:0;visibility:hidden}}
/* Herbst/Winter reagieren stärker sichtbar */
.app-shell.season-autumn .wall-fixed .tree-scene-v22{filter:sepia(.35) saturate(1.2) hue-rotate(-15deg) drop-shadow(0 15px 10px rgba(62,39,18,.3))!important}
.app-shell.season-winter .wall-fixed .tree-scene-v22{filter:saturate(.45) brightness(1.18) drop-shadow(0 15px 10px rgba(58,75,84,.3))!important}
.app-shell.season-spring .wall-fixed .tree-scene-v22:after{content:'🌸  🌸  🌸';position:absolute;left:14%;right:14%;top:15%;font-size:20px;letter-spacing:38px;animation:blossomPulse 3s ease-in-out infinite}
@keyframes blossomPulse{0%,100%{transform:scale(.96);opacity:.72}50%{transform:scale(1.04);opacity:1}}
@media(prefers-reduced-motion:reduce){.morning-intro{display:none}.hero-fox,.tree-scene-v22,.child-card-v22,.sunbeam,.forest-bird,.forest-butterfly{animation:none!important}}
body.reward-celebration .wall-fixed:after{content:'✨  🍃  ⭐  🍃  ✨';position:absolute;inset:8% 0 auto;text-align:center;font-size:34px;z-index:70;animation:rewardBurst 2.5s ease forwards;pointer-events:none}@keyframes rewardBurst{0%{opacity:0;transform:translateY(80px) scale(.5)}35%{opacity:1;transform:translateY(0) scale(1.2)}100%{opacity:0;transform:translateY(-90px) scale(.8)}}

/* =========================================================
   DigiBoard Next 11.45 – kompakte Einstellungs-Arbeitsflächen
   ========================================================= */
#settingsDialog .settings-card{height:min(840px,calc(100dvh - 28px));overflow:hidden}
#settingsDialog .dialog-head{min-height:62px;padding:10px 18px;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:18px}
#settingsDialog .settings-title-block h2{font-size:22px;line-height:1;margin:1px 0}
#settingsDialog .settings-title-block .eyebrow{font-size:9px}
#settingsDialog .settings-title-block .dialog-subtitle{font-size:11px;margin:2px 0 0}
#settingsDialog .settings-detail-bar{margin:0;padding:0 12px;border:0;background:transparent;display:flex;align-items:center;gap:12px;min-width:0}
#settingsDialog .settings-detail-bar[hidden]{display:none}
#settingsDialog .settings-detail-bar button{height:34px;padding:0 12px}
#settingsDialog .settings-detail-bar strong{font-size:17px;white-space:nowrap}
#settingsDialog .settings-detail-bar span{font-size:10px;margin-left:auto}
#settingsDialog .settings-section:not([hidden]),#settingsDialog details.settings-accordion:not([hidden]){height:calc(100% - 78px);margin:8px 16px 10px;overflow:hidden}
#settingsDialog .daily-settings-grid{height:calc(100% - 62px)}
#settingsDialog .daily-card{height:100%;overflow:hidden;padding:10px 12px}
#settingsDialog .editor-head{display:none}

/* Tagesinfos: vier Zeilen plus Vorschau ohne innere Scrollbalken */
#settingsDialog .info-composer-layout{grid-template-columns:minmax(0,1.65fr) minmax(300px,.85fr);gap:12px;height:calc(100% - 30px)}
#settingsDialog .info-line-editor-panel,#settingsDialog .info-line-editor{overflow:visible;min-width:0}
#settingsDialog .info-editor-row{padding:5px 7px 5px 12px;margin:0 0 5px;gap:5px;min-height:78px}
#settingsDialog .info-row-number{width:22px;height:22px;font-size:11px;left:-7px;top:-5px}
#settingsDialog .info-text-fields{grid-template-columns:48px 1fr 1fr;gap:5px}
#settingsDialog .info-text-fields select,#settingsDialog .info-text-fields input{height:31px;padding:4px 7px;font-size:12px}
#settingsDialog .info-text-fields select{font-size:18px;text-align:center}
#settingsDialog .info-format-tools{grid-template-columns:31px repeat(4,minmax(0,1fr)) 30px;gap:4px;margin-top:4px}
#settingsDialog .info-format-tools label{font-size:8px}
#settingsDialog .info-format-tools select,#settingsDialog .info-format-tools button,#settingsDialog .info-bold-toggle{height:27px;min-height:27px;font-size:10px;padding:2px 5px}
#settingsDialog .add-info-line{height:30px;margin-top:2px}
#settingsDialog .info-live-preview{height:100%;min-height:0;padding:12px}
#settingsDialog .info-preview-row{min-height:46px;padding:8px}

/* Aufgaben: Eingabe, Vorlagen und echte Tafelvorschau nebeneinander */
.task-editor-layout{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(300px,.8fr);gap:14px;height:100%}
.task-form-panel{display:flex;flex-direction:column;gap:8px;min-width:0}
.task-fields{display:grid;grid-template-columns:.65fr 1.35fr;gap:8px}
.task-fields label:nth-child(3){grid-column:1/-1}
.task-fields input,.task-fields textarea{font-size:14px;min-height:40px}
.task-template-head{display:flex;align-items:center;justify-content:space-between}.task-template-head button{padding:8px 12px;border-radius:10px}
.task-favorites{display:grid;grid-template-columns:1fr 1fr;gap:7px}
.task-favorites>button{display:flex;align-items:center;gap:9px;text-align:left;padding:8px;border:1px solid #cbdcbc;border-radius:12px;background:#fff}
.task-favorites>button>span{font-size:24px}.task-favorites strong,.task-favorites small{display:block}.task-favorites small{max-width:250px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#61725c}
.task-live-preview{border:6px solid #704323;border-radius:22px;padding:16px;background:linear-gradient(160deg,#1d7158,#0c4e40);color:#fff;box-shadow:0 10px 22px #254d2833}
.task-live-preview>small{font-size:9px;letter-spacing:1.5px}.task-live-preview article{margin-top:18px;padding:18px;border-radius:16px;background:#fff9e9;color:#244d32;box-shadow:0 5px 14px #193b293d}.task-live-preview article span{font-size:10px;letter-spacing:1px}.task-live-preview h4{font-size:25px;margin:6px 0}.task-live-preview p{font-size:17px;font-weight:750}.task-live-preview em{display:block;margin-top:14px;padding-top:10px;border-top:1px dashed #b7c4a5;color:#6c684d}

/* Kinderverwaltung: saubere Fotokarten und verständliches Pausieren */
#settingsDialog .class-management-toolbar{padding:8px 12px;min-height:64px}
#settingsDialog .class-management-toolbar .panel-help{max-width:850px;font-size:11px}
#settingsDialog .class-student-grid{grid-template-columns:repeat(4,minmax(0,1fr))!important;gap:8px;padding:8px;max-height:calc(100% - 78px);overflow:auto}
#settingsDialog .class-student-card{display:grid!important;grid-template-columns:56px 1fr!important;grid-template-rows:auto auto!important;gap:6px 8px!important;padding:8px!important;min-height:122px}
#settingsDialog .class-student-photo{grid-row:1}.class-roster-photo{width:52px!important;height:52px!important}
#settingsDialog .class-student-copy{display:grid;grid-template-columns:1fr 1fr;gap:4px}.class-student-copy small{grid-column:1/-1;font-size:9px}
#settingsDialog .class-student-copy input{height:31px;font-size:12px;padding:4px 6px}
#settingsDialog .class-student-actions{grid-column:1/-1;display:grid!important;grid-template-columns:1.35fr .9fr;gap:6px;padding-left:56px}
#settingsDialog .class-student-actions>*{height:32px!important;min-height:32px!important;font-size:10px!important;padding:5px 8px!important;justify-content:flex-start}

/* Ein Stundenplan-Bereich mit zwei klaren Ansichten */
.schedule-workspace{padding:10px!important}
.schedule-mode-tabs{display:flex;gap:6px;padding:4px;background:#edf5e4;border:1px solid #cadcbc;border-radius:13px;margin-bottom:8px}
.schedule-mode-tabs button{flex:1;height:38px;border:0;border-radius:9px;background:transparent;font-weight:800;color:#315a37}.schedule-mode-tabs button.active{background:linear-gradient(90deg,#fff1a8,#bfe985);box-shadow:0 3px 8px #355b2630}
.schedule-workspace>section{height:calc(100% - 54px);overflow:auto}
.schedule-plan-head,.simple-day-change-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 12px;background:#f7faef;border:1px solid #d3e0c7;border-radius:12px;margin-bottom:7px}
.schedule-plan-head h3,.simple-day-change-head h3{font-size:18px;margin:0}.schedule-plan-head p,.simple-day-change-head p{font-size:10px;margin:2px 0}
.week-schedule-editor,.override-editor{display:grid;gap:4px}.schedule-edit-row,.override-row{min-height:45px!important;padding:4px 7px!important}
.override-row{grid-template-columns:minmax(210px,.9fr) 160px 1fr 1fr!important}.override-base{display:grid!important;grid-template-columns:30px 95px 1fr;align-items:center}.override-base small{grid-column:3}
.override-break-row,.schedule-break-row{min-height:30px!important;padding:4px 12px!important}

@media(max-width:760px){
  #settingsDialog .settings-card{height:100dvh;max-height:none;border-radius:0}
  #settingsDialog .dialog-head{grid-template-columns:1fr auto;padding:8px 10px}.settings-title-block .dialog-subtitle,.settings-title-block .eyebrow{display:none}
  #settingsDialog .settings-detail-bar{grid-column:1/-1;order:3;padding:0}.settings-detail-bar span{display:none}
  #settingsDialog .info-composer-layout,.task-editor-layout{grid-template-columns:1fr;overflow:auto}.info-live-preview,.task-live-preview{min-height:260px}
  #settingsDialog .info-text-fields{grid-template-columns:44px 1fr}.info-text-fields input:last-child{grid-column:2}
  #settingsDialog .info-format-tools{grid-template-columns:30px repeat(2,1fr) 30px}
  #settingsDialog .class-student-grid{grid-template-columns:1fr!important}
  .override-row{grid-template-columns:1fr!important}.schedule-plan-head,.simple-day-change-head{align-items:flex-start;flex-direction:column}
}

