/* Warnleiste, wenn saveState() nicht speichern konnte (z. B. Speicher voll).
   Vorher gab es in diesem Fall ueberhaupt keine Rueckmeldung. */
#storageWarningBar{
  position:fixed;
  left:50%;
  bottom:max(18px,env(safe-area-inset-bottom,0px));
  transform:translateX(-50%);
  z-index:9999;
  display:flex;
  align-items:flex-start;
  gap:14px;
  max-width:min(680px,calc(100vw - 32px));
  padding:14px 16px;
  border-radius:14px;
  border:2px solid #8a3b12;
  background:#fff4e2;
  color:#5b2708;
  font:600 15px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif;
  box-shadow:0 12px 34px rgba(0,0,0,.32);
  animation:storageWarningIn .22s ease-out;
}

