  html body .app-shell .forest-light::after{
    content:""!important;
    position:absolute!important;
    z-index:1!important;
    inset:0!important;
    display:block!important;
    pointer-events:none!important;
    border-radius:inherit!important;
    background:
      radial-gradient(ellipse 62% 58% at 50% 62%,transparent 0 46%,rgba(10,48,28,.13) 76%,rgba(8,40,24,.27) 100%),
      radial-gradient(ellipse 44% 36% at 50% 56%,rgba(255,250,214,.20),transparent 68%)!important;
  }
  html body .app-shell.time-evening .forest-light::after{
    background:
      radial-gradient(ellipse 60% 56% at 50% 62%,transparent 0 42%,rgba(6,34,22,.22) 74%,rgba(5,28,19,.40) 100%),
      radial-gradient(ellipse 42% 34% at 50% 56%,rgba(255,214,150,.16),transparent 66%)!important;
  }

  /* Ferne Nadelbaeume und Hain bleiben, verlieren aber Schaerfe und Farbe.
     Genau dieser Unterschied laesst den Hauptbaum vortreten. */
  html body .app-shell .wall-fixed .tree-depth-pines-v1542{
    opacity:.62!important;
    filter:blur(1.5px) saturate(.72) brightness(1.03)!important;
